import type { User } from './types.js';
import { loadUser } from './api.js';
// type imports erased; value imports stay

// Avoid deep recursion in types — TS errors at depth limit
type Deep<T, D extends number = 5> = D extends 0
  ? T
  : T extends object ? { [K in keyof T]: Deep<T[K], Prev<D>> } : T;
type Prev<N extends number> = [-1,0,1,2,3,4][N];
